import React from 'react';

import { GraduationCap, Users, Key, FileText, Rss, BookOpen, Book } from 'lucide-react';

const AnnouncementsScroll = () => {
    // Top navigation links mimicking the original site layout
    const quickLinks = [
        { name: 'FACILITIES', icon: GraduationCap },
        { name: 'ADMISSION', icon: Users, active: true },
        { name: 'HOSTEL', icon: GraduationCap },
        { name: 'LOGIN', icon: Key },
        { name: 'DISCLOSURES', icon: FileText },
        { name: 'BLOG', icon: Rss },
        { name: 'NEWS-EVENTS', icon: BookOpen },
        { name: 'CENTRAL LIBRARY', icon: Book },
    ];

    const announcements = [
        "Result -B. Arch S6 (S) Exam, November 2025 (2022 Scheme)",
        "Result- B. Arch S1 (R) Exam, December 2025 (2023 Scheme)",
        "KTU Academic Calendar 2025-26 published online.",
        "Last date for Fee Remittance extended to 10th Jan 2026."
    ];

    const upcomingEvents = [
        "» TKM College of Engineering Kollam is organizing the 10th International Conference on Human Values in Higher Education to be held from 19th to 21st December 2025.",
        "» The Department of Chemical Engineering is organizing a Six-day AICTE Training and Learning (ATAL) Online Faculty Development Programme.",
        "» Orientation program for First-Year Students scheduled for next Monday."
    ];

    const events = [
        "» The 7th International Conference on Modelling and Simulation",
        "» Summer internship program - EEE",
        "» Internship on Optical Communication Design with Optisystem",
        "» Annual Sports Meet 2025 scheduled for March."
    ];

    return (
        <section className="bg-[#fcfbf9] py-14 relative border-b-[6px] border-coral overflow-hidden">
            {/* Background geometric pattern commonly seen in college websites (using faint radial gradients to simulate the pattern) */}
            <div className="absolute inset-0 opacity-[0.04] pointer-events-none" style={{ backgroundImage: 'repeating-linear-gradient(45deg, #000 25%, transparent 25%, transparent 75%, #000 75%, #000), repeating-linear-gradient(45deg, #000 25%, transparent 25%, transparent 75%, #000 75%, #000)', backgroundPosition: '0 0, 10px 10px', backgroundSize: '20px 20px' }}></div>

            <div className="relative z-10 mx-auto max-w-[1440px] px-4 lg:px-8">
                {/* Horizontal Quick Links */}
                <div className="mb-12 flex flex-wrap justify-center gap-3">
                    {quickLinks.map((link, idx) => (
                        <button
                            key={idx}
                            className={`flex items-center gap-2 rounded-[5px] px-[20px] py-[10px] text-[0.8rem] font-bold uppercase tracking-wider transition-all duration-300 ${
                                link.active 
                                    ? 'bg-[#a32a2a] text-white shadow-md hover:bg-[#882121]' 
                                    : 'bg-[#cca86e] text-white hover:bg-[#b08e5c] shadow-sm' 
                            }`}
                        >
                            <link.icon size={18} className="opacity-80" />
                            {link.name}
                        </button>
                    ))}
                </div>

                {/* 3 Columns of Auto-scrolling Layout */}
                <div className="grid gap-6 md:grid-cols-3">

                    {/* Column 1: Announcement */}
                    <div className="h-[350px] overflow-hidden rounded-[14px] bg-white/90 p-7 shadow-[0_4px_30px_rgba(0,0,0,0.04)] backdrop-blur-sm border border-black/[0.03] flex flex-col group">
                        <h3 className="mb-6 text-center font-display text-[1.5rem] font-bold text-[#8c4613]">
                            Announcement
                        </h3>
                        {/* Scroll Mask Container */}
                        <div className="relative flex-1 overflow-hidden" style={{ maskImage: 'linear-gradient(to bottom, transparent, black 10%, black 90%, transparent)', WebkitMaskImage: 'linear-gradient(to bottom, transparent, black 10%, black 90%, transparent)' }}>
                            {/* Scrolling Track */}
                            <div className="absolute top-full w-full animate-scrollY group-hover:[animation-play-state:paused] flex flex-col gap-6">
                                {announcements.concat(announcements).map((text, idx) => (
                                    <div key={idx} className="flex gap-3 text-[0.95rem] leading-relaxed text-slate-700">
                                        <span className="text-red-500 font-bold shrink-0 text-[0.7rem] bg-yellow-100 px-1 py-[2px] rounded h-fit mt-1">NEW</span>
                                        <p>{text}</p>
                                    </div>
                                ))}
                            </div>
                        </div>
                    </div>

                    {/* Column 2: Upcoming Events */}
                    <div className="h-[350px] overflow-hidden rounded-[14px] bg-white/90 p-7 shadow-[0_4px_30px_rgba(0,0,0,0.04)] backdrop-blur-sm border border-black/[0.03] flex flex-col group">
                        <h3 className="mb-6 text-center font-display text-[1.5rem] font-bold text-[#8c4613]">
                            Upcoming Events
                        </h3>
                        <div className="relative flex-1 overflow-hidden" style={{ maskImage: 'linear-gradient(to bottom, transparent, black 10%, black 90%, transparent)', WebkitMaskImage: 'linear-gradient(to bottom, transparent, black 10%, black 90%, transparent)' }}>
                            <div className="absolute top-full w-full animate-scrollY group-hover:[animation-play-state:paused] flex flex-col gap-6" style={{ animationDelay: '-6s' }}>
                                {upcomingEvents.concat(upcomingEvents).map((text, idx) => (
                                    <p key={idx} className="text-[0.95rem] leading-relaxed text-slate-700">
                                        {text}
                                    </p>
                                ))}
                            </div>
                        </div>
                    </div>

                    {/* Column 3: Events */}
                    <div className="h-[350px] overflow-hidden rounded-[14px] bg-white/90 p-7 shadow-[0_4px_30px_rgba(0,0,0,0.04)] backdrop-blur-sm border border-black/[0.03] flex flex-col group">
                        <h3 className="mb-6 text-center font-display text-[1.5rem] font-bold text-[#8c4613]">
                            Events
                        </h3>
                        <div className="relative flex-1 overflow-hidden" style={{ maskImage: 'linear-gradient(to bottom, transparent, black 10%, black 90%, transparent)', WebkitMaskImage: 'linear-gradient(to bottom, transparent, black 10%, black 90%, transparent)' }}>
                            <div className="absolute top-full w-full animate-scrollY group-hover:[animation-play-state:paused] flex flex-col gap-6" style={{ animationDelay: '-12s' }}>
                                {events.concat(events).map((text, idx) => (
                                    <p key={idx} className="text-[0.95rem] leading-relaxed text-slate-700 border-b border-slate-100 pb-4">
                                        {text}
                                    </p>
                                ))}
                            </div>
                        </div>
                    </div>

                </div>
            </div>
        </section>
    );
};

export default AnnouncementsScroll;
